/* Real Houston campus locations. All drone routes and activity are simulated. */
const houstonMapState={map:null,center:null,zoom:null,focus:'',pendingFocus:null,routesVisible:true,basemap:'streets',markers:new Map(),observer:null,facilityLayer:null,routeLayer:null,rangeLayer:null,plannedRouteLayer:null,tileLayer:null};
const houstonBasemaps={
  streets:{url:'https://basemap.nationalmap.gov/arcgis/rest/services/USGSTopo/MapServer/tile/{z}/{y}/{x}',name:'USGS map'},
  imagery:{url:'https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryTopo/MapServer/tile/{z}/{y}/{x}',name:'Aerial imagery'}
};
function mapPanel(){return `<section class="panel map-panel ${state.view==='network'?'expanded-map':''}"><div class="panel-head"><div><h2>Greater Houston, connected.</h2><p>${facilities.length} network facilities. A wider horizon for care.</p></div><div class="head-actions"><span class="live-pill"><span class="status-dot"></span>${facilities.length} facilities</span><button class="button secondary join-network-button" data-join-network>${icon('plus')}Join the network</button><button class="icon-button" data-action="map-reset" aria-label="Show entire Houston network">${icon('target')}</button></div></div><div class="houston-map-toolbar"><label class="map-facility-search">${icon('search')}<select id="map-facility" aria-label="Find a Houston facility"><option value="">Explore all ${facilities.length} facilities</option>${facilities.map(f=>`<option value="${f.id}" ${houstonMapState.focus===f.id?'selected':''}>${escapeHtml(f.name)}</option>`).join('')}</select></label><div class="map-layer-actions"><button class="map-layer-button ${houstonWeatherState.visible?'active':''}" data-map-action="weather" aria-expanded="${houstonWeatherState.visible}" aria-controls="houston-weather">${weatherIcon('partly')}Weather</button><button class="map-layer-button ${houstonMapState.routesVisible?'active':''}" data-map-action="routes" aria-pressed="${houstonMapState.routesVisible}">${icon('network')}Demo routes</button><select id="map-basemap" aria-label="Map background"><option value="streets" ${houstonMapState.basemap==='streets'?'selected':''}>Street map</option><option value="imagery" ${houstonMapState.basemap==='imagery'?'selected':''}>Aerial imagery</option></select></div></div><div class="map-range-policy"><span class="range-limit">${icon('target')}10 mi clear · 5 mi low visibility</span><p id="map-range-summary">Only direct connections of 10 miles or less are shown. Choose a hospital to see its reach.</p><button class="button text range-details" id="map-range-details" data-facility="" hidden>Hospital details ${icon('arrow-right')}</button></div>${flightWeatherControls()}${houstonRoutingPanel()}${hospitalDeliveryTrackingPanel()}<div class="houston-map-layout ${houstonWeatherState.visible?'has-weather':''}"><div class="network-map houston-map-frame"><div id="houston-map" role="region" aria-label="Interactive Houston hospital map. Scroll to zoom, drag to pan, use plus and minus to zoom, or select a source and destination hospital."></div><div class="map-location-badge">${icon('hospital')}GREATER HOUSTON <span>${facilities.length} hospital & lab locations</span></div><div class="map-tile-notice" id="map-tile-notice" role="status" hidden>Map imagery is unavailable. Check your internet connection or switch the background.</div></div>${houstonWeatherPanel()}</div><div class="houston-map-footer"><div><span class="legend-pair"><span class="legend-hospital"></span>Real hospital</span><span class="legend-pair"><span class="legend-joined-lab"></span>Joined lab</span><span class="legend-pair"><span class="legend-line"></span>≤10 mi connection</span><span class="legend-pair"><span class="legend-drone"></span>Demo drone</span><span class="legend-pair"><span class="legend-range"></span>10-mile reach</span><span class="legend-pair"><span class="legend-outside"></span>Outside direct range</span><span class="legend-pair"><span class="legend-relay"></span>Planned route</span><span class="legend-pair"><span class="legend-flight"></span>Delivery path</span><span class="legend-pair"><span class="legend-weather-blocked"></span>Weather blocked</span><span class="legend-pair"><span class="legend-weather-rain"></span>Demo rain zone</span><span class="legend-pair"><span class="legend-weather-visibility"></span>Demo visibility: 5 mi</span><span class="map-cluster-hint">Scroll to zoom · Drag to pan · Select a grouped pin to zoom</span></div><p>Distances are direct campus-to-campus miles. Clear-weather hops allow 10 miles; low visibility reduces them to 5 miles. Demo routes use the fewest allowed hops and avoid blocked weather zones. Demo routes are not approved flight paths.</p></div></section>`;}
function disposeHoustonMap(){flightWeatherState.zoneLayer=null;disposeHoustonDeliveryMap();disposeHoustonWeather();const s=houstonMapState;if(s.map){s.center=s.map.getCenter();s.zoom=s.map.getZoom();s.map.remove();s.map=null;}s.observer?.disconnect();s.observer=null;s.markers.clear();}
const MAX_ROUTE_MILES=10;
const KM_PER_MILE=1.609344;
function routeDistanceKm(from,to){
  const a=facilities.find(f=>f.id===from),b=facilities.find(f=>f.id===to);if(!a||!b)return NaN;
  const rad=Math.PI/180,dLat=(b.lat-a.lat)*rad,dLng=(b.lng-a.lng)*rad;
  const h=Math.min(1,Math.sin(dLat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dLng/2)**2);
  return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));
}
function routeDistanceMiles(from,to){return routeDistanceKm(from,to)/KM_PER_MILE;}
function routeWithinRange(from,to){return from!==to&&routeDistanceMiles(from,to)<=MAX_ROUTE_MILES;}
function formatRouteMiles(miles){return Number.isFinite(miles)?miles.toFixed(miles>10&&miles<10.1?2:1):'—';}
function reachableHospitals(from){return facilities.filter(f=>routeWithinRange(from,f.id)).sort((a,b)=>routeDistanceMiles(from,a.id)-routeDistanceMiles(from,b.id));}
function routeRangeMessage(from,to){const miles=routeDistanceMiles(from,to);return Number.isFinite(miles)?'This route is '+formatRouteMiles(miles)+' miles. The maximum is '+MAX_ROUTE_MILES+' miles between hospitals.':'Choose two valid hospitals.';}
function drawHoustonCoverage(){
  const s=houstonMapState;if(!s.map)return;s.rangeLayer.clearLayers();refreshHoustonWeather();
  const summary=document.getElementById('map-range-summary'),details=document.getElementById('map-range-details');if(details){details.hidden=!s.focus;details.dataset.facility=s.focus||'';}
  if(!s.focus){if(summary)summary.textContent='Only direct connections of 10 miles or less are shown. Choose a hospital to see its reach.';return;}
  const f=facility(s.focus),demo=flightWeatherState.mode==='demo',readings=demoWeatherRegionsAt(f.lat,f.lng).map(r=>flightWeatherScenarios[flightWeatherState.regions[r.id]]),maxMiles=demo?Math.min(MAX_ROUTE_MILES,...readings.map(flightWeatherRangeMiles)):MAX_ROUTE_MILES,blocked=demo&&readings.some(r=>flightWeatherReasons(r).length),reachable=reachableHospitals(f.id).filter(to=>!demo||demoFlightWeatherLeg(f.id,to.id).status==='clear');
  L.circle([f.lat,f.lng],{radius:maxMiles*KM_PER_MILE*1000,color:blocked?'#c54b43':maxMiles===5?'#ca9133':'#47775d',weight:1.5,dashArray:'5 6',fillColor:'#84ad76',fillOpacity:.13,interactive:false,className:'houston-range-circle'}).addTo(s.rangeLayer);
  if(summary)summary.textContent=f.short+' · '+(blocked?'Demo weather blocks launch here':reachable.length+' '+(reachable.length===1?'allowed connection':'allowed connections')+' · '+maxMiles+' mi local range'+(maxMiles===5?' due to low visibility':''));
}
function campusPopup(f){const el=document.createElement('div');el.className='houston-popup';el.innerHTML=`<span class="popup-eyebrow">HOUSTON HOSPITAL</span><h3>${escapeHtml(f.name)}</h3><p>${escapeHtml(f.address)}</p><div class="popup-meta"><span>${escapeHtml(f.city)}</span><span>Demo hub ${f.pad}</span></div><p class="popup-range"><strong>${reachableHospitals(f.id).length}</strong> ${reachableHospitals(f.id).length===1?'nearby hospital':'nearby hospitals'} within 10 miles</p><p class="popup-disclaimer">Real location · Demo operations</p><button class="button primary" data-map-details="${f.id}">View facility ${icon('arrow-right')}</button><a class="popup-source" href="${f.source}" target="_blank" rel="noopener noreferrer">Official location ↗</a>`;el.querySelector('button').addEventListener('click',()=>facilityDetails(f.id));return el;}
function routePopup(d){const el=document.createElement('div');el.className='houston-popup';el.innerHTML=`<span class="popup-eyebrow">SIMULATED DELIVERY</span><h3>${d.id}</h3><p class="popup-route">${escapeHtml(facility(d.from).short)}<span>→</span>${escapeHtml(facility(d.to).short)}</p><div class="popup-meta"><span>${formatRouteMiles(routeDistanceMiles(d.from,d.to))} mi direct</span><span>${escapeHtml(d.drone||'Unassigned')}</span></div><p class="popup-disclaimer">${escapeHtml(d.cargo)} · ${d.priority}<br>Illustrative flight, not live telemetry</p><button class="button primary">View demo delivery ${icon('arrow-right')}</button>`;el.querySelector('button').addEventListener('click',()=>deliveryDetails(d.id));return el;}
function applyHoustonBasemap(){const s=houstonMapState;if(!s.map)return;if(s.tileLayer)s.map.removeLayer(s.tileLayer);const notice=document.getElementById('map-tile-notice');if(notice)notice.hidden=true;const settings=houstonBasemaps[s.basemap];s.tileLayer=L.tileLayer(settings.url,{maxNativeZoom:16,maxZoom:18,minZoom:8,attribution:'Map: <a href="https://www.usgs.gov/programs/national-geospatial-program/national-map" target="_blank" rel="noopener noreferrer">USGS The National Map</a>',keepBuffer:1});s.tileLayer.on('tileerror',()=>{if(notice)notice.hidden=false;});s.tileLayer.on('tileload',()=>{if(notice)notice.hidden=true;});s.tileLayer.addTo(s.map);}
// Group nearby campuses in screen space; individual lookup always remains available.
function houstonCampusGroups(){
  const map=houstonMapState.map,focus=houstonMapState.focus,groups=[],clustered=map.getZoom()<14;
  const pinned=new Set([focus,houstonRoutingState.source,houstonRoutingState.destination,...(houstonRoutingState.path||[]),...state.deliveries.filter(d=>d.flight&&deliveryRouteIsValid(d)&&d.status==='In transit').flatMap(d=>d.flight.path)].filter(Boolean));
  for(const f of facilities){
    const point=map.latLngToContainerPoint([f.lat,f.lng]);
    const group=clustered&&!pinned.has(f.id)?groups.find(g=>!pinned.has(g.facilities[0].id)&&(!focus||routeWithinRange(focus,g.facilities[0].id)===routeWithinRange(focus,f.id))&&g.point.distanceTo(point)<36):null;
    if(group){group.facilities.push(f);group.point=L.point(group.facilities.reduce((v,c)=>v+map.latLngToContainerPoint([c.lat,c.lng]).x,0)/group.facilities.length,group.facilities.reduce((v,c)=>v+map.latLngToContainerPoint([c.lat,c.lng]).y,0)/group.facilities.length);}
    else groups.push({facilities:[f],point});
  }
  return groups;
}
function drawHoustonFacilities(){
  const s=houstonMapState;if(!s.map)return;s.facilityLayer.clearLayers();s.markers.clear();
  const groups=houstonCampusGroups(),reserved=[],size=s.map.getSize();
  const intersects=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
  for(const g of groups)reserved.push({x:g.point.x-18,y:g.point.y-18,w:36,h:36});
  for(const group of groups){
    const campuses=group.facilities,f=campuses[0],count=campuses.length;
    const center=count===1?[f.lat,f.lng]:[campuses.reduce((v,c)=>v+c.lat,0)/count,campuses.reduce((v,c)=>v+c.lng,0)/count];
    const area=campuses.every(c=>c.city===f.city)?f.city:'Houston area';
    const label=count>1?area+' · '+count:f.short;
    const outside=s.focus&&campuses.every(c=>c.id!==s.focus&&(!routeWithinRange(s.focus,c.id)||(flightWeatherState.mode==='demo'&&demoFlightWeatherLeg(s.focus,c.id).status!=='clear')));
    const routeRole=count===1?hospitalRouteRole(f.id):'',routeNumber=houstonRoutingState.path?.indexOf(f.id)+1;
    const pinText=routeRole==='source-destination'?'S/D':routeRole==='source'?'S':routeRole==='destination'?'D':routeRole==='intermediate'?String(routeNumber):icon(f.custom?'flask':'plus');
    const preferred=count>1?'bottom':f.direction,w=Math.min(185,label.length*5.5+15),h=23,p=group.point;
    const labelRect=direction=>({x:direction==='left'?p.x-23-w:direction==='right'?p.x+23:p.x-w/2,y:direction==='top'?p.y-23-h:direction==='bottom'?p.y+23:p.y-h/2,w,h});
    const directions=[preferred,...['bottom','top','right','left'].filter(d=>d!==preferred)];
    const clearDirection=directions.find(d=>{const r=labelRect(d);return r.x>5&&r.x+w<size.x-5&&r.y>5&&r.y+h<size.y-5&&!reserved.some(b=>intersects(r,b));});
    const direction=clearDirection||preferred,permanent=Boolean(clearDirection);
    if(permanent)reserved.push(labelRect(direction));
    const marker=L.marker(center,{title:count>1?area+' — '+count+' facilities. Select to zoom in.':f.name,alt:count>1?label:f.name,icon:L.divIcon({className:'houston-hospital-marker'+(outside?' is-out-of-range':'')+(f.id===s.focus?' is-selected':'')+(f.custom?' is-joined-lab':'')+(routeRole?' is-route-'+routeRole:''),html:count>1?'<span class="hospital-pin cluster-pin">'+count+'</span>':'<span class="hospital-pin">'+pinText+'</span>',iconSize:count>1?[36,36]:[30,30],iconAnchor:count>1?[18,18]:[15,15],popupAnchor:[0,-14]}),zIndexOffset:routeRole?400:0}).bindTooltip(escapeHtml(label),{permanent,direction,offset:direction==='top'?[0,-18]:direction==='bottom'?[0,18]:direction==='left'?[-18,0]:[18,0],className:'houston-hospital-label'}).addTo(s.facilityLayer);
    if(count>1)marker.on('click',()=>{s.focus='';const select=document.getElementById('map-facility');if(select)select.value='';drawHoustonCoverage();drawHoustonRoutes();s.map.fitBounds(L.latLngBounds(campuses.map(c=>[c.lat,c.lng])),{padding:[70,70],maxZoom:15,animate:false});drawHoustonFacilities();});
    else{
      marker.on('click',()=>selectHospitalOnMap(f.id));
      marker.on('keypress',event=>{
        if(event.originalEvent.key==='Enter'){
          selectHospitalOnMap(f.id);
          s.markers.get(f.id)?.getElement()?.focus({preventScroll:true});
        }
      });
      s.markers.set(f.id,marker);
    }
    const el=marker.getElement();el?.setAttribute('data-campus-count',String(count));el?.setAttribute('aria-label',count>1?'Explore '+count+' facilities in '+area:'Select '+f.name+' on map');
    if(count===1){el?.setAttribute('data-route-role',routeRole);el?.setAttribute('data-facility-id',f.id);el?.setAttribute('aria-pressed',String(f.id===s.focus));}
  }
}
// A link represents a direct hospital pair within the same 10-mile policy.
function houstonNetworkLinks(){const links=[];for(let i=0;i<facilities.length;i++)for(let j=i+1;j<facilities.length;j++){const from=facilities[i],to=facilities[j];if(routeWithinRange(from.id,to.id))links.push([from,to]);}return links;}
function drawHoustonRoutes(){const s=houstonMapState;if(!s.map)return;drawPlannedHospitalRoute();drawHoustonDeliveryFlights();s.routeLayer.clearLayers();if(!s.routesVisible)return;for(const [from,to] of houstonNetworkLinks()){
    if(s.focus&&!houstonRoutingState.path&&from.id!==s.focus&&to.id!==s.focus)continue;
    const miles=routeDistanceMiles(from.id,to.id),weather=flightWeatherState.mode==='demo'?demoFlightWeatherLeg(from.id,to.id):null;
    const line=L.polyline([[from.lat,from.lng],[to.lat,to.lng]],{pane:'demoRoutes',color:weather?.status==='blocked'?'#c54b43':weather?.maxMiles===5?'#ca9133':'#41785f',weight:s.focus?2.5:1.5,opacity:s.focus ? .7 : .3,dashArray:'4 6',className:'houston-network-link'}).bindTooltip(escapeHtml(from.short)+' → '+escapeHtml(to.short)+' · '+formatRouteMiles(miles)+' mi'+(weather?' · '+(weather.status==='blocked'?'Weather blocked':weather.maxMiles+' mi limit'):''),{sticky:true}).addTo(s.routeLayer);
    line.getElement()?.setAttribute('data-route-miles',String(miles));line.getElement()?.setAttribute('data-route-allowed',String(weather?.status!=='blocked'));line.getElement()?.setAttribute('data-route-limit',String(weather?.maxMiles||10));
    line.getElement()?.setAttribute('data-route-from',from.id);line.getElement()?.setAttribute('data-route-to',to.id);
  }state.deliveries.filter(d=>d.status==='In transit'&&!d.flight&&routeWithinRange(d.from,d.to)).forEach((d,i)=>{const from=facility(d.from),to=facility(d.to),points=[[from.lat,from.lng],[to.lat,to.lng]];L.polyline(points,{color:'#fff',weight:6,opacity:.7,interactive:false}).addTo(s.routeLayer);const route=L.polyline(points,{color:d.priority==='Urgent'?'#a57b34':'#205947',weight:3,opacity:.9,dashArray:'7 8',className:'houston-demo-route'}).bindPopup(()=>routePopup(d),{maxWidth:270,minWidth:210}).bindTooltip(`${d.id} · ${formatRouteMiles(routeDistanceMiles(d.from,d.to))} mi direct`,{sticky:true}).addTo(s.routeLayer);route.getElement()?.setAttribute('data-route-miles',String(routeDistanceMiles(d.from,d.to)));const progress=Math.min(.85,.32+i*.11);L.marker([from.lat+(to.lat-from.lat)*progress,from.lng+(to.lng-from.lng)*progress],{title:`Demo flight ${d.id}`,icon:L.divIcon({className:'houston-drone-marker',html:`<span class="drone-pin">${icon('drone')}</span>`,iconSize:[30,30],iconAnchor:[15,15],popupAnchor:[0,-15]})}).bindPopup(()=>routePopup(d),{maxWidth:270,minWidth:210}).addTo(s.routeLayer).getElement()?.setAttribute('aria-label',`Track demo flight ${d.id}`);route.getElement()?.setAttribute('aria-label',`Demo route ${d.id}`);});}
function fitHoustonNetwork({clearRoute=true}={}){const s=houstonMapState;if(!s.map)return;if(clearRoute){resetHospitalRouteState();renderHoustonRouting();}s.map.invalidateSize({pan:false,debounceMoveend:true});s.map.closePopup();s.focus='';const select=document.getElementById('map-facility');if(select)select.value='';s.map.fitBounds(L.latLngBounds(facilities.map(f=>[f.lat,f.lng])),{padding:[55,55],maxZoom:12,animate:false});drawHoustonCoverage();drawHoustonRoutes();drawHoustonFacilities();}
function focusHoustonFacility(id,{fitCoverage=true,openPopup=false}={}){
  const s=houstonMapState;if(!s.map||!facilities.some(f=>f.id===id))return;
  s.map.closePopup();s.focus=id;
  const select=document.getElementById('map-facility');if(select)select.value=id;
  drawHoustonCoverage();
  if(fitCoverage){const range=s.rangeLayer.getLayers()[0];s.map.fitBounds(range.getBounds(),{padding:[25,100],maxZoom:12,animate:false});}
  drawHoustonFacilities();drawHoustonRoutes();
  if(openPopup)s.markers.get(id)?.openPopup();
}
function mountHoustonMap(){const element=document.getElementById('houston-map');if(!element)return;if(typeof L==='undefined'){element.innerHTML='<div class="empty-state">The map library could not load. The hospital directory below is still available.</div>';return;}const s=houstonMapState;s.map=L.map(element,{zoomControl:true,scrollWheelZoom:true,trackResize:false,wheelPxPerZoomLevel:90,wheelDebounceTime:80,minZoom:8,maxZoom:18,zoomSnap:.25,zoomAnimation:!state.settings.motion,fadeAnimation:false,markerZoomAnimation:!state.settings.motion,maxBounds:[[29.2,-96.1],[30.3,-94.6]],maxBoundsViscosity:.5});s.map.attributionControl.setPrefix('<a href="https://leafletjs.com/" target="_blank" rel="noopener noreferrer">Leaflet</a>');s.map.createPane('demoRoutes');s.map.getPane('demoRoutes').style.zIndex=410;s.map.createPane('weatherZones');s.map.getPane('weatherZones').style.zIndex=390;s.map.getPane('weatherZones').style.pointerEvents='none';s.map.createPane('weatherLabels');s.map.getPane('weatherLabels').style.zIndex=405;s.map.getPane('weatherLabels').style.pointerEvents='none';s.map.createPane('deliveryRoutes');s.map.getPane('deliveryRoutes').style.zIndex=450;s.map.createPane('deliveryDrones');s.map.getPane('deliveryDrones').style.zIndex=650;s.map.createPane('plannedRoutes');s.map.getPane('plannedRoutes').style.zIndex=430;s.facilityLayer=L.layerGroup().addTo(s.map);s.routeLayer=L.layerGroup().addTo(s.map);s.rangeLayer=L.layerGroup().addTo(s.map);s.plannedRouteLayer=L.layerGroup().addTo(s.map);applyHoustonBasemap();if(s.center&&s.zoom&&s.lastView===state.view)s.map.setView(s.center,s.zoom,{animate:false});else fitHoustonNetwork({clearRoute:false});s.lastView=state.view;drawHoustonCoverage();drawHoustonRoutes();drawHoustonFacilities();L.control.scale({imperial:true,metric:false,position:'bottomleft',maxWidth:90}).addTo(s.map);s.map.on('zoomend',()=>{drawHoustonFacilities();drawPlannedHospitalRoute();});s.observer=new ResizeObserver(()=>{if(s.map){s.map.invalidateSize({pan:false,debounceMoveend:true});if(houstonRoutingState.path?.length>1)fitPlannedHospitalRoute();else{drawHoustonFacilities();drawPlannedHospitalRoute();}}});s.observer.observe(element);if(s.pendingFocus){const id=s.pendingFocus;s.pendingFocus=null;focusHoustonFacility(id);}mountHoustonWeather();drawDemoWeatherZones();renderHoustonDeliveryTracking();renderFlightWeatherViews();queueFlightWeatherCheck(houstonRoutingState.path);drawPlannedHospitalRoute();if(houstonRoutingState.path?.length>1)fitPlannedHospitalRoute();}
document.addEventListener('change',event=>{if(event.target.id==='map-facility'){if(event.target.value)focusHoustonFacility(event.target.value);else fitHoustonNetwork();}if(event.target.id==='map-basemap'){houstonMapState.basemap=event.target.value;applyHoustonBasemap();}});
document.addEventListener('click',event=>{const button=event.target.closest('[data-map-action],[data-map-focus]');if(!button)return;if(button.dataset.mapAction==='routes'){houstonMapState.routesVisible=!houstonMapState.routesVisible;button.classList.toggle('active',houstonMapState.routesVisible);button.setAttribute('aria-pressed',String(houstonMapState.routesVisible));drawHoustonRoutes();}if(button.dataset.mapFocus){const id=button.dataset.mapFocus;closeModal();if(state.view==='network'||state.view==='overview')focusHoustonFacility(id);else{houstonMapState.pendingFocus=id;location.hash='network';}document.querySelector('.map-panel')?.scrollIntoView({behavior:state.settings.motion?'auto':'smooth',block:'start'});}});

